#include "Container.hpp"
#include "OPF.hpp"
#include "Content.hpp"
#include "CSS.hpp"

using std::vector;
using std::size_t;

class Epub {

	private:
		bool from_epub;

	public:

		path filename;
		path absolute_path;

		size_t hash;
		string hash_string;

		path directory_path;

		Container container;
		vector<OPF> opf_files;
		vector<CSS> css;
		vector<Content> contents;

