		Epub(sqlite3 * const db, const unsigned int file_id);

		Epub(Epub const & cpy);
		Epub(Epub && mv);
		Epub & operator =(const Epub & cpy);
		Epub & operator =(Epub && mv);

		~Epub() ;

		void save_to(sqlite3 * const db);

		static inline size_t compute_epub_hash(const path & _absolute_path);

};

