201: 	//setup collation keys for improved speed:
202: 	const string metadata_key = ustring("metadata").collate_key();
203: 	const string manifest_key = ustring("manifest").collate_key();
204: 	const string item_key = ustring("item").collate_key();
205: 	const string href_key = ustring("href").collate_key();
206: 	const string id_key = ustring("id").collate_key();
207: 	const string media_type_key = ustring("media-type").collate_key();
208: 	const string spine_key = ustring("spine").collate_key();
209: 	const string toc_key = ustring("toc-type").collate_key();
210: 	const string itemref_key = ustring("itemref").collate_key();
211: 	const string idref_key = ustring("idref").collate_key();
212: 	const string linear_key = ustring("linear").collate_key();
