227: 
228: 			auto mdlist = mdnode->get_children();
229: 
230: 			for(auto mditer = mdlist.begin(); mditer != mdlist.end(); ++mditer) {
231: 
232: 				Node * metadatatmp = *mditer;
233: 
234: 				//Still genuinely horrible.
235: 				const Element * metadatanode = dynamic_cast<const Element *>(metadatatmp);
