266: 				for(auto iter = attributes.begin(); iter != attributes.end(); ++iter) {
267: 					const Attribute * attribute = *iter;
268: 					const ustring namespace_prefix = attribute->get_namespace_prefix();
269: 					ustring attrname = attribute->get_name();
270: 					ustring attrvalue = attribute->get_value();
271: 					md.add_attribute(attrname, attrvalue);
272: 				}
273: 
274: 				metadata.insert(pair<MetadataType, MetadataItem>(mdtype, md));
275: 
276: 			}
277: 		}
278: 
279: 		if(mdnode->get_name().collate_key() == manifest_key)  {
280: 
281: 			auto mlist = mdnode->get_children();
282: 
283: 			for(auto miter = mlist.begin(); miter != mlist.end(); ++miter) {
284: 
285: 				Node * itemtmp = *miter;
286: 
287: 				//Still genuinely horrible.
288: 				const Element * itemnode = dynamic_cast<const Element *>(itemtmp);
289: 
290: 				if(!itemnode) {
291: 					continue;
292: 				}
293: 
294: 				ustring name = itemnode->get_name();
295: 
296: 				if(name.collate_key() != item_key) {
297: 					continue;
298: 				}
299: 
300: 				ustring href, id, media_type;
301: 				const auto attributes = itemnode->get_attributes();
302: 
303: 				for(auto iter = attributes.begin(); iter != attributes.end(); ++iter) {
304: 					const Attribute * attribute = *iter;
305: 					const ustring namespace_prefix = attribute->get_namespace_prefix();
306: 					ustring attrname = attribute->get_name();
