312: 					else if(attrname.collate_key() == id_key) {
313: 						id = attrvalue;
314: 					}
315: 					else if(attrname.collate_key() == media_type_key) {
316: 						media_type = attrvalue;
317: 					}
318: 				}
319: 
320: 				ManifestItem tmp(href, id, media_type);
321: 				manifest.insert(pair<ustring, ManifestItem>(id, tmp));
322: 
323: 				#ifdef DEBUG
