325: 				#endif
326: 
327: 			}
328: 		}
329: 
330: 		if(mdnode->get_name().collate_key() == spine_key)  {
331: 
332: 			auto mlist = mdnode->get_children();
333: 			{
334: 
335: 				const auto attributes = mdnode->get_attributes();
