354: 			for(auto miter = mlist.begin(); miter != mlist.end(); ++miter) {
355: 
356: 				Node * itemtmp = *miter;
357: 
358: 				//Still genuinely horrible.
359: 				const Element * itemnode = dynamic_cast<const Element *>(itemtmp);
360: 
361: 				if(!itemnode) {
362: 					continue;
363: 				}
364: 
365: 				ustring name = itemnode->get_name();
