406: OPF::OPF(sqlite3 * const db, const unsigned int epub_file_id, const unsigned int opf_index)
407: {
408: 
409: 	int rc;
410: 
411: 	const string metadata_select_sql = "SELECT metadata_id, metadata_type, contents FROM metadata WHERE epub_file_id=? AND opf_id=?;";
412: 	const string metadata_tags_select_sql = "SELECT tagname, tagvalue FROM metadata_tags WHERE metadata_id=?;";
413: 	const string manifest_select_sql = "SELECT href, id, media_type FROM manifest WHERE epub_file_id=? AND opf_id=?;";
414: 	const string spine_select_sql = "SELECT idref, linear FROM spine WHERE epub_file_id=? AND opf_id=?;";
415: 
416: 	sqlite3_stmt * metadata_select;
417: 	sqlite3_stmt * metadata_tags_select;
418: 	sqlite3_stmt * manifest_select;
419: 	sqlite3_stmt * spine_select;
420: 
421: 	rc = sqlite3_prepare_v2(db, metadata_select_sql.c_str(), -1, &metadata_select, 0);
422: 
423: 	if(rc != SQLITE_OK && rc != SQLITE_DONE) {
424: 		throw - 1;
425: 	}
426: 
427: 	rc = sqlite3_prepare_v2(db, metadata_tags_select_sql.c_str(), -1, &metadata_tags_select, 0);
428: 
429: 	if(rc != SQLITE_OK && rc != SQLITE_DONE) {
430: 		throw - 1;
431: 	}
432: 
433: 	rc = sqlite3_prepare_v2(db, manifest_select_sql.c_str(), -1, &manifest_select, 0);
434: 
435: 	if(rc != SQLITE_OK && rc != SQLITE_DONE) {
436: 		throw - 1;
437: 	}
438: 
439: 	rc = sqlite3_prepare_v2(db, spine_select_sql.c_str(), -1, &spine_select, 0);
440: 
441: 	if(rc != SQLITE_OK && rc != SQLITE_DONE) {
442: 		throw - 1;
443: 	}
444: 
445: 	sqlite3_bind_int(metadata_select, 1, epub_file_id);
446: 	sqlite3_bind_int(metadata_select, 2, opf_index);
447: 
448: 	rc = sqlite3_step(metadata_select);
449: 
450: 	while ( rc == SQLITE_ROW ) {
451: 
452: 		//Get the basic data
453: 		unsigned int metadata_id = sqlite3_column_int(metadata_select, 0);
454: 		MetadataType mdtype = (MetadataType) sqlite3_column_int(metadata_select, 1);
455: 		ustring content = sqlite3_column_ustring(metadata_select, 2);
456: 
457: 		//Create the object
458: 		MetadataItem md(mdtype, content);
459: 
460: 		int rc2;
461: 
462: 		sqlite3_bind_int(metadata_tags_select, 1, metadata_id);
463: 
464: 		rc2 = sqlite3_step(metadata_tags_select);
465: 
466: 		while(rc2 == SQLITE_ROW) {
467: 
468: 			ustring tagname = sqlite3_column_ustring(metadata_tags_select, 0);
469: 			ustring tagvalue = sqlite3_column_ustring(metadata_tags_select, 1);
470: 
471: 			md.add_attribute(tagname, tagvalue);
472: 
473: 			rc2 = sqlite3_step(metadata_tags_select);
474: 
475: 		}
476: 
477: 		metadata.insert(pair<MetadataType, MetadataItem>(mdtype, md));
478: 
479: 		sqlite3_reset(metadata_tags_select);
480: 
481: 		rc = sqlite3_step(metadata_select);
482: 
483: 	}
484: 
485: 	sqlite3_bind_int(manifest_select, 1, epub_file_id);
486: 	sqlite3_bind_int(manifest_select, 2, opf_index);
487: 
488: 	rc = sqlite3_step(manifest_select);
489: 
490: 	while ( rc == SQLITE_ROW ) {
491: 
492: 		ustring href = sqlite3_column_ustring(manifest_select, 0);
493: 		ustring id = sqlite3_column_ustring(manifest_select, 1);
494: 		ustring media_type = sqlite3_column_ustring(manifest_select, 2);
495: 
496: 		ManifestItem tmp(href, id, media_type);
497: 		manifest.insert(pair<ustring, ManifestItem>(id, tmp));
498: 
499: 		rc = sqlite3_step(manifest_select);
500: 
501: 	}
502: 
503: 	sqlite3_bind_int(spine_select, 1, epub_file_id);
504: 	sqlite3_bind_int(spine_select, 2, opf_index);
505: 
506: 	rc = sqlite3_step(spine_select);
507: 
508: 	while ( rc == SQLITE_ROW ) {
509: 
510: 		ustring idref = sqlite3_column_ustring(spine_select, 0);
511: 		bool linear = (bool) sqlite3_column_int(spine_select, 1);
512: 
513: 		SpineItem tmp(idref, linear);
514: 		spine.push_back(tmp);
515: 
516: 		rc = sqlite3_step(spine_select);
517: 
518: 	}
519: 
520: 	sqlite3_finalize(metadata_select);
521: 	sqlite3_finalize(metadata_tags_select);
522: 	sqlite3_finalize(manifest_select);
523: 	sqlite3_finalize(spine_select);
524: 
525: }
