597: void OPF::save_to(sqlite3 * const db, const unsigned int epub_file_id, const unsigned int opf_index)
598: {
599: 	int rc;
600: 	char * errmsg;
601: 
602: 	const string opf_table_sql = "CREATE TABLE IF NOT EXISTS opf("  \
603: 	                             "epub_file_id INTEGER NOT NULL," \
604: 	                             "opf_id INTEGER NOT NULL) ;";
605: 	sqlite3_exec(db, opf_table_sql.c_str(), NULL, NULL, &errmsg);
606: 
607: 	const string metadata_table_sql = "CREATE TABLE IF NOT EXISTS metadata("  \
608: 	                                  "metadata_id INTEGER PRIMARY KEY," \
609: 	                                  "epub_file_id INTEGER NOT NULL," \
610: 	                                  "opf_id INTEGER NOT NULL," \
611: 	                                  "metadata_type INTEGER NOT NULL," \
612: 	                                  "contents TEXT NOT NULL) ;";
613: 	sqlite3_exec(db, metadata_table_sql.c_str(), NULL, NULL, &errmsg);
614: 
615: 	const string metadata_tags_table_sql = "CREATE TABLE IF NOT EXISTS metadata_tags("  \
616: 	                                       "metadata_id INTEGER NOT NULL," \
617: 	                                       "tagname TEXT NOT NULL," \
618: 	                                       "tagvalue TEXT NOT NULL) ;";
619: 	sqlite3_exec(db, metadata_tags_table_sql.c_str(), NULL, NULL, &errmsg);
620: 
621: 	const string manifest_table_sql = "CREATE TABLE IF NOT EXISTS manifest("  \
622: 	                                  "epub_file_id INTEGER NOT NULL," \
623: 	                                  "opf_id INTEGER NOT NULL," \
624: 	                                  "href TEXT NOT NULL," \
625: 	                                  "id TEXT NOT NULL," \
626: 	                                  "media_type TEXT NOT NULL) ;";
627: 	sqlite3_exec(db, manifest_table_sql.c_str(), NULL, NULL, &errmsg);
628: 
629: 	const string spine_table_sql = "CREATE TABLE IF NOT EXISTS spine("  \
630: 	                               "epub_file_id INTEGER NOT NULL," \
631: 	                               "opf_id INTEGER NOT NULL," \
632: 	                               "idref TEXT NOT NULL," \
633: 	                               "linear INTEGER NOT NULL) ;";
634: 	sqlite3_exec(db, spine_table_sql.c_str(), NULL, NULL, &errmsg);
635: 
636: 	//Tables created.
637: 
638: 	sqlite3_stmt * opf_insert;
639: 	sqlite3_stmt * metadata_insert;
640: 	sqlite3_stmt * metadata_tags_insert;
641: 	sqlite3_stmt * manifest_insert;
642: 	sqlite3_stmt * spine_insert;
643: 
644: 	const string opf_insert_sql = "INSERT INTO opf (epub_file_id, opf_id) VALUES (?, ?);";
645: 	const string metadata_insert_sql = "INSERT INTO metadata (epub_file_id, opf_id, metadata_type, contents) VALUES (?, ?, ?, ?);";
646: 	const string metadata_tags_insert_sql = "INSERT INTO metadata_tags (metadata_id, tagname, tagvalue) VALUES (?, ?, ?);";
647: 	const string manifest_insert_sql = "INSERT INTO manifest (epub_file_id, opf_id, href, id, media_type) VALUES (?, ?, ?, ?, ?);";
648: 	const string spine_insert_sql = "INSERT INTO spine (epub_file_id, opf_id, idref, linear) VALUES (?, ?, ?, ?);";
649: 
650: 	rc = sqlite3_prepare_v2(db, opf_insert_sql.c_str(), -1, &opf_insert, 0);
651: 
652: 	if(rc != SQLITE_OK && rc != SQLITE_DONE) {
653: 		throw - 1;
654: 	}
655: 
656: 	rc = sqlite3_prepare_v2(db, metadata_insert_sql.c_str(), -1, &metadata_insert, 0);
657: 
658: 	if(rc != SQLITE_OK && rc != SQLITE_DONE) {
659: 		throw - 1;
660: 	}
661: 
662: 	rc = sqlite3_prepare_v2(db, metadata_tags_insert_sql.c_str(), -1, &metadata_tags_insert, 0);
663: 
664: 	if(rc != SQLITE_OK && rc != SQLITE_DONE) {
665: 		throw - 1;
666: 	}
667: 
668: 	rc = sqlite3_prepare_v2(db, manifest_insert_sql.c_str(), -1, &manifest_insert, 0);
669: 
670: 	if(rc != SQLITE_OK && rc != SQLITE_DONE) {
671: 		throw - 1;
672: 	}
673: 
674: 	rc = sqlite3_prepare_v2(db, spine_insert_sql.c_str(), -1, &spine_insert, 0);
675: 
676: 	if(rc != SQLITE_OK && rc != SQLITE_DONE) {
677: 		throw - 1;
678: 	}
679: 
680: 	//Populate the OPF table:
681: 	sqlite3_bind_int(opf_insert, 1, epub_file_id);
682: 	sqlite3_bind_int(opf_insert, 2, opf_index);
683: 
684: 	rc = sqlite3_step(opf_insert);
685: 
686: 	if(rc != SQLITE_OK && rc != SQLITE_ROW && rc != SQLITE_DONE) {
687: 		throw - 1;
688: 	}
689: 
690: 	for(auto & mi : metadata) {
691: 
692: 		sqlite3_bind_int(metadata_insert, 1, epub_file_id);
693: 		sqlite3_bind_int(metadata_insert, 2, opf_index);
694: 		sqlite3_bind_int(metadata_insert, 3, mi.second.type);
695: 		sqlite3_bind_text(metadata_insert, 4, mi.second.contents.c_str(), -1, SQLITE_STATIC);
696: 
697: 		int result = sqlite3_step(metadata_insert);
698: 
699: 		if(result != SQLITE_OK && result != SQLITE_ROW && result != SQLITE_DONE) {
700: 			throw - 1;
701: 		}
702: 
703: 		sqlite3_reset(metadata_insert);
704: 
705: 		//get the new id:
706: 		auto key = sqlite3_last_insert_rowid(db);
707: 
708: 		for(auto tags : mi.second.other_tags) {
709: 
710: 			sqlite3_bind_int(metadata_tags_insert, 1, key);
