	pair<ustring, ustring> __recursive_strip(vector<ContentItem> & items, const CSS & css, const path & file, const Node * const node)
	{

		const TextNode * nodeText = dynamic_cast<const TextNode *>(node);

		if(nodeText) {
			if(nodeText->is_white_space()) {
